    nodes = case['nodes']
    required = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n['parent']
        if p is not None:
            children[p].append(n['id'])
    retained = set(node_map.keys())
    removal_order = []
    # Sort by depth descending, then by ID ascending (string)
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for n in sorted_nodes:
        nid = n['id']
        if (n['removable'] and nid != 'root' and n['symbol'] not in required):
            # Check if all children have been removed (none in retained)
            if all(cid not in retained for cid in children[nid]):
                retained.remove(nid)
                removal_order.append(nid)
    return {
        'retained': sorted(retained),
        'removal_order': removal_order
    }
